use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let mut counts = HashMap::new();
    for item in input {
        let str_item = item.as_str().unwrap();
        *counts.entry(str_item).or_insert(0) += 1;
    }
    let mut most_frequent = None;
    let mut max_count = 0;
    for (str_item, count) in counts {
        if count > max_count || (count == max_count && str_item < most_frequent.as_ref().unwrap()) {
            most_frequent = Some(str_item);
            max_count = count;
        }
    }
    most_frequent.map_or(Value::null, |str_item| Value::String(str_item.to_string()))
}
